550      private static List<Set<FType>> coverParts(FType t, List<FType> at, Set<FType> path, int[] steps) {
551          if (--steps[0] < 0) return null;
552          if (t instanceof SymbolicType) return null;
553          List<Set<FType>> res = new ArrayList<Set<FType>>();
554          try {
555              boolean belowAll = true;
556              for (int j = 0; belowAll && j < at.size(); j++) belowAll = t.subtypeOf(at.get(j));
557              Set<FType> tc = t.getComprises();
558              if (belowAll || tc == null) {
559                  res.add(Collections.singleton(t));
560                  return res;
561              }
562              if (!path.add(t)) return null;
563              for (FType c : tc) {
564                  List<Set<FType>> sub = coverParts(c, at, path, steps);
565                  if (sub == null) return null;
566                  res.addAll(sub);
567              }
568              path.remove(t);
569              return res;
570          }
571          catch (FortressException ex) {
572              return null;
573          }
574      }

