/* Check the set of overloadings in this compilation unit:
 *
 * For every trait and object, check dotted methods and functional methods, taking inheritance into account
 * Check top-level functions, taking functional methods and top-level variables into account
 * Check local functions, taking local variables into account
 *
 * The following features are not (fully) checked yet:
 *     static parameters
 *     exclusion relationships
 *     varargs parameters
 *     keyword parameters
 */
class OverloadingChecker(compilation_unit: CompilationUnitIndex,
                         globalEnv: GlobalEnvironment) {
    var typeAnalyzer = TypeAnalyzer.make(new TraitTable(compilation_unit, globalEnv))
    val globalOracle = new OverloadingOracle()(typeAnalyzer)
    var errors = List[StaticError]()

    private final val cacheOverloadChecks = ProjectProperties.getBoolean("fortress.analyzer.overload.cache", true)

    private def getFunctionsFromCompilationUnit(index: CompilationUnitIndex,
                                                f: IdOrOpOrAnonymousName)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      getFunctions(index, f, compilation_unit.isInstanceOf[ComponentIndex])

    private def getFunctions(index: CompilationUnitIndex,
                             f: IdOrOpOrAnonymousName)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      getFunctions(index, f, false)

    private def getFunctions(index: CompilationUnitIndex,
                             f: IdOrOpOrAnonymousName,
                             onlyConcrete: Boolean)
        : List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
      val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
      val fns = toFunctionArrows(fndecls, onlyConcrete)
      if ( index.variables.keySet.contains(f) )
        index.variables.get(f) match {
          case SDeclaredVariable(lvalue)
               if lvalue.getIdType.unwrap.isInstanceOf[ArrowType] =>
            fns :+ ((lvalue.getIdType.unwrap.asInstanceOf[ArrowType], None, None))
          case _ => fns
        }
      else fns
    }

    private def getFunctionalMethods(index: CompilationUnitIndex, f: IdOrOpOrAnonymousName): List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
        val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
        val fndeclsfiltered = fndecls.filter(f => f.isInstanceOf[JavaFunctionalMethod])
        toFunctionArrows(fndeclsfiltered, false)
    }

    private def getDeclaredFunctions(index: CompilationUnitIndex, f: IdOrOpOrAnonymousName): List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
        val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
        val fndeclsfiltered = fndecls.filter(f => f.isInstanceOf[DeclaredFunction])
        toFunctionArrows(fndeclsfiltered, false)
    }    

    private def toFunctionArrows(set: Set[JavaFunctional], onlyConcrete: Boolean):
        List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      set.filter(s => isFunction(s) &&
                      (!onlyConcrete || s.asInstanceOf[JavaFunctional].body.isSome))
         .toList.map(f => (NF.makeArrowType(f.getSpan,
				     paramsToType(f.parameters, f.getSpan),
				     f.getReturnType.unwrap,
				     getStaticParameters(f, true)),
		           if (isFunctionalMethod(f))
			     Some(f.asInstanceOf[JavaFunctionalMethod].selfPosition)
			   else None,
			   Some(f)))

    // for functional methods: in a component those with a body and every one inherited from
    // an api, as the top-level set reads a component's own declarations and an imported api's;
    // in an api every one; but an abstract one implemented by a declaration of a subtype
    // with the same parameter types
    private def toFunctionalMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)],
                                         oracle: OverloadingOracle):
        List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
      val inComponent = compilation_unit.isInstanceOf[ComponentIndex]
      val arrows = set.filter(p => p match { case (f, _, tt) => isFunctionalMethod(f) &&
                                               (!inComponent || f.asInstanceOf[JavaFunction].body.isSome ||

                                               (!inComponent || f.asInstanceOf[JavaFunction].body.isSome ||
                                                !declaredInUnit(tt))})
         .toList.map(p => p match { case (f, replacer, tt) =>
              //TODO: Figure out whether I should get the lifted parameters or not. The original code DID.  I think the answer is NO. 2/21/2012
              val (sparams, apart) = ownStaticParamsApart(f)
              ((NF.makeArrowType(f.getSpan,
                                replacer.replaceIn(apart(paramsToType(f.parameters, f.getSpan))),
                                replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams),
               Some(f.asInstanceOf[JavaFunctionalMethod].selfPosition),
	       Some(f)), tt)})
      def implemented(a: (ArrowType,Option[Int],Option[JavaFunctional]), tt: TraitType) =
        a._3.get.asInstanceOf[JavaFunction].body.isNone &&
        arrows.exists(p => p match { case (c, ctt) =>
          !(c._1 eq a._1) && c._2 == a._2 && typeAnalyzer.lteq(ctt, tt) && !typeAnalyzer.lteq(tt, ctt) &&
          oracle.equiv(a._1, c._1) })
      arrows.filter(p => !implemented(p._1, p._2)).map(_._1)
    }

    /* A declaration's parameter types without self, as the trait or object being checked
     * has them, over the method's own static parameters renamed apart (ownStaticParamsApart):
     * what STypesUtil.providedMethods compares. */
    private def paramsWithoutSelf(d: (JavaFunctional, StaticTypeReplacer, TraitType)): Option[Type] = d match {
      case (f, replacer, _) =>
        val ps = toListFromImmutable(f.parameters)
        val kept = f match {
          case m: JavaFunctionalMethod => ps.zipWithIndex.filter(_._2 != m.selfPosition).map(_._1)
          case _ => ps }
        STypesUtil.paramsToType(kept, f.getSpan).map { t =>
          val (sparams, apart) = ownStaticParamsApart(f)
          replacer.replaceIn(insertStaticParams(apart(t), sparams)) }
    }

    // whether the trait or object is declared in this compilation unit, not in an api it imports
    private def declaredInUnit(tt: TraitType): Boolean = {
      val ti = typeAnalyzer.traits.typeCons(tt.getName)
      if (ti.isNone) return false
      val own = compilation_unit.typeConses.values.iterator
      while (own.hasNext) if (own.next eq ti.unwrap) return true
      false
    }

    // for dotted methods
    private def toMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)])
                           : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      set.filter(p => p match { case (f, _, _) => isDeclaredMethod(f)})
         .toList.map(p => p match { case (f, replacer, _) =>
              val (sparams, apart) = ownStaticParamsApart(f)
              (NF.makeArrowType(f.getSpan,
	                        replacer.replaceIn(apart(paramsToType(f.asInstanceOf[JavaMethod].selfType.unwrap, f.parameters, f.getSpan))),
                		replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams),
               None,
	       Some(f))})

    /* An inherited method's own static parameters, each whose name is a static parameter
     * of the trait or object being checked renamed apart, so that the arguments the
     * replacer puts in place of the declaring trait's parameters are not captured. */
    private def ownStaticParamsApart(f: JavaFunctional): (JavaList[StaticParam], Type => Type) = {
      val own = toListFromImmutable(getStaticParameters(f, false))
      val env = typeAnalyzer.env
      val taken = own.map(_.getName.getText).toSet
      val clash = own.filter(p => env.contains(p.getName))
      if (clash.isEmpty) return (getStaticParameters(f, false), (t: Type) => t)
      val subst: List[(IdOrOp, IdOrOp)] = clash.map { p =>
        val n = p.getName
        val fresh = Iterator.from(1).map(i => NF.makeId(NU.getSpan(n), n.getText + "$" + i))
                            .find(m => !env.contains(m) && !taken.contains(m.getText)).get
        (n, fresh) }
